cat > "$ROOT/privacy/index.html" <<EOF
<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="index,follow"><title>سياسة الخصوصية | كورت إكسبرت</title><meta name="description" content="سياسة خصوصية طلبات التواصل في موقع كورت إكسبرت"><link rel="canonical" href="$DOMAIN/privacy/"><link rel="stylesheet" href="/assets/styles.css"></head><body>$H<main><section><div class="c privacy"><h1>سياسة الخصوصية</h1><p>نجمع الاسم ورقم الجوال وملخص الطلب ومعلومات الإسناد الإعلاني عند توفرها بغرض التواصل مع صاحب الطلب وتوجيهه للقسم المناسب وقياس أداء قنوات التسويق.</p><h2>استخدام البيانات</h2><p>تستخدم البيانات في التواصل والمتابعة وتحسين جودة القياس ومنع إساءة استخدام النموذج. لا يتم طلب معلومات حساسة في نموذج البداية.</p><h2>التواصل</h2><p>للاستفسار: <a href="mailto:$EMAIL">$EMAIL</a></p></div></section></main>$F</body></html>
EOF
cat > "$ROOT/robots.txt" <<EOF
User-agent: *
Allow: /
Sitemap: $DOMAIN/sitemap.xml
EOF
cat > "$ROOT/sitemap.xml" <<EOF
<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><url><loc>$DOMAIN/</loc></url><url><loc>$DOMAIN/riyadh-lawyer/</loc></url><url><loc>$DOMAIN/legal-consultation/</loc></url><url><loc>$DOMAIN/labor-law/</loc></url><url><loc>$DOMAIN/debt-collection-execution/</loc></url><url><loc>$DOMAIN/trademark-intellectual-property/</loc></url><url><loc>$DOMAIN/family-inheritance/</loc></url><url><loc>$DOMAIN/business-commercial-law/</loc></url><url><loc>$DOMAIN/real-estate-law/</loc></url><url><loc>$DOMAIN/criminal-specialized/</loc></url><url><loc>$DOMAIN/privacy/</loc></url></urlset>
EOF
printf '%s\n' "$SHA" > "$ROOT/RELEASE"
test -s "$ROOT/index.html"
test -s "$ROOT/riyadh-lawyer/index.html"
test -s "$ROOT/assets/logo.png"
test -s "$ROOT/assets/hero.jpg"
grep -Fq "$GTM" "$ROOT/index.html"
grep -Fq "/assets/logo.png" "$ROOT/index.html"
grep -Fq "/assets/hero.jpg" "$ROOT/assets/styles.css"
! grep -Fq "نية البحث والإعلان" "$ROOT/index.html"
printf 'CORTS_DEPLOY_OK:%s\n' "$SHA"
